// The gateway computes the same digests, blob and floor as the contracts, using
// the inputs and outputs committed in contracts/test/fixtures/mldsa.json
// (generated by tools/fixtures/gen.mjs and accepted by the Foundry tests).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { bytesToHex, hexToBytes, keccak256, recoverMessageAddress, type Hex } from "viem";
import { prepareBlob } from "../../../tools/mldsa/prepare.mjs";
import { prepareBlob as prepareBlobOldPath } from "../../../tools/fixtures/prepare.mjs";
import { batchDigest, popDigest } from "../../lib/digest.ts";
import { largeLiftCount, mldsaVerify, requireNonDegenerate } from "../../lib/keys.ts";

const fx = JSON.parse(readFileSync(new URL("../../../contracts/test/fixtures/mldsa.json", import.meta.url), "utf8"));
const chainId = BigInt(fx.chainId);

test("popDigest equals the fixture's for every key", () => {
  for (const [name, deviceId] of [["keyA1", fx.deviceA], ["keyA2", fx.deviceA], ["keyB1", fx.deviceB]] as const) {
    const k = fx[name];
    assert.equal(keccak256(k.pk), k.pkHash);
    assert.equal(popDigest(chainId, fx.registry, deviceId, k.version, k.ecdsaSigner, k.pkHash), k.popDigest, name);
  }
});

test("batchDigest equals the fixture's for every batch, and its signatures check", async () => {
  for (const b of fx.batches) {
    const d = batchDigest(chainId, fx.readingLog, {
      deviceId: b.deviceId, passportId: BigInt(b.passportId), seq: BigInt(b.seq), root: b.root,
      fromTs: BigInt(b.fromTs), toTs: BigInt(b.toTs), count: b.count,
    });
    assert.equal(d, b.digest);
    const signer = await recoverMessageAddress({ message: { raw: d }, signature: b.ecdsaSig });
    const key = [fx.keyA1, fx.keyA2].find((k) => k.ecdsaSigner === signer);
    assert.ok(key, "batch signed by a fixture key");
    assert.ok(mldsaVerify(d, b.mldsaSig, hexToBytes(key.pk)));
  }
});

test("prepareBlob reproduces the fixture blobs, from both import paths", () => {
  for (const name of ["keyA1", "keyB1"]) {
    const pk = hexToBytes(fx[name].pk as Hex);
    assert.equal(bytesToHex(prepareBlob(pk)), fx[name].blob);
    assert.equal(bytesToHex(prepareBlobOldPath(pk)), fx[name].blob);
  }
});

test("off-chain floor agrees with MLDSAKey.sol on the fixture cases", () => {
  assert.ok(largeLiftCount(hexToBytes(fx.keyA1.pk)) > 950);
  requireNonDegenerate(hexToBytes(fx.keyB1.pk));
  assert.equal(largeLiftCount(hexToBytes(fx.degeneratePk)), 0);
  const maximal = hexToBytes(fx.keyA1.pk);
  maximal.fill(0xff, 32);
  assert.equal(largeLiftCount(maximal), 0);
  assert.throws(() => requireNonDegenerate(maximal), /degenerate/);
  assert.throws(() => largeLiftCount(new Uint8Array(1313)), /1312/);
});
